verify_lift.code:
def verify_lift(sdk, target_height):
    for check in range(3):
        state = sdk.get_state()
        if state["objects"]["cube"]["pos"][2] < target_height:
            return False
        if check < 2:
            if remaining_steps(sdk) < 6:
                return False
            actuate_gripper(sdk, "close", steps=6)
    return True

