servo.code:
def servo(sdk, target, yaw, grip, steps=36, tolerance=0.004):
    bias = [0.0, 0.0, 0.0]
    remaining = min(steps, budget(sdk))
    while remaining > 0 and budget(sdk) > 0:
        before = sdk.get_state()["steps_used"]
        count = min(12, remaining, budget(sdk))
        sdk.move_to(
            [target[i] + bias[i] for i in range(3)],
            yaw=yaw, gripper=grip, max_steps=count, tol=0.002
        )
        state = sdk.get_state()
        consumed = state["steps_used"] - before
        if consumed <= 0:
            return False
        remaining -= consumed
        error = [target[i] - state["eef_pos"][i] for i in range(3)]
        distance = sqrt(sum(value * value for value in error))
        if distance < tolerance:
            return True
        if distance < 0.040:
            for i in range(3):
                bias[i] = max(-0.018, min(0.018, bias[i] + 0.6 * error[i]))
    return False

square_error.code:
def square_error(target, current):
    return atan2(sin(4.0 * (target - current)),
                 cos(4.0 * (target - current))) / 4.0

